import 'package:flutter/material.dart';
class InputBar extends StatelessWidget { final TextEditingController controller; final VoidCallback onSend; const InputBar({super.key, required this.controller, required this.onSend}); @override Widget build(BuildContext context) { return Container(padding: const EdgeInsets.all(8), decoration: BoxDecoration(color: Theme.of(context).colorScheme.surface, border: Border(top: BorderSide(color: Theme.of(context).dividerColor))), child: Row(children: [IconButton(icon: const Icon(Icons.mic), onPressed: () {}), Expanded(child: TextField(controller: controller, decoration: const InputDecoration(hintText: 'اكتب رسالة...', border: OutlineInputBorder()), onSubmitted: (_) => onSend())), IconButton(icon: const Icon(Icons.send), onPressed: onSend)])); } }
